variables.input:
// filter timeseries by the selected cluster
timeseries count(`dt.kubernetes.nodes`), by: {name=k8s.cluster.name}
| fields name
| sort name asc
// if no clusters, add * placeholder to avoid errors
| summarize entries = collectDistinct(name)
| fields records = if (arraySize(entries) > 0, entries, else: { "*" })
| expand records

// filter timeseries by the selected ActiveGate
timeseries sum(dt.sfm.active_gate.kubernetes.api.query_duration), by:{dt.active_gate.id, k8s.cluster.name}
| fields dt.active_gate.id, k8s.cluster.name
| filter matchesValue(k8s.cluster.name, $Cluster )
// if no activeGates, add * placeholder to avoid errors
| summarize entries = collectArray(dt.active_gate.id)
| fields records = if(arraySize(entries) > 0, entries, else: { "no-activegates" })
| expand records

1.query:
timeseries { sum(dt.sfm.active_gate.kubernetes.api.query_count, rate: 1m), value.A = avg(dt.sfm.active_gate.kubernetes.api.query_count, rate: 1m, scalar: true) }, by: { path, k8s.cluster.name }, filter: { matchesValue(dt.active_gate.id, $ActiveGateId) AND matchesValue(k8s.cluster.name, $Cluster) }
| sort value.A desc
| limit 10

8.query:
timeseries
  // Query the self-monitoring metric for API requests to endpoints of monitored Kubernetes clusters
  queries = sum(dt.sfm.active_gate.kubernetes.api.query_count, scalar: true),
  // Apply desired grouping
  by: { k8s.cluster.name, dt.active_gate.id, path, status_code, status_reason, access_type },
  // Filter out successful requests - status code 200
  filter: { matchesValue(k8s.cluster.name, $Cluster ) AND NOT matchesValue(status_code, "2*") AND (matchesValue(dt.active_gate.id, $ActiveGateId)) }
// Sort by the number of failed requests
| sort queries desc
// Add ActiveGateUrl as intent link to the ActiveGate details in Fleet Management
| fieldsAdd activeGateURL = concat("/ui/intent/dynatrace.fleet.management/view-entity-dt.smartscape.activegate#%7B%22dt.active_gate.id%22%3A%22", dt.active_gate.id, "%22%7D")
| fieldsAdd activeGateLink = concat("[",dt.active_gate.id,"](",activeGateURL,")")
// Rename fields for better visualization
| fieldsRename `Top failing queries in total` = queries, `Cluster name` = k8s.cluster.name, `ActiveGate ID` = activeGateLink, `Path` = path, `Status code` = status_code, `Status reason` = status_reason, `Access type` = access_type

15.query:
// Fetch Kubernetes clusters filtered by selected cluster name or ActiveGate ID
smartscapeNodes "K8S_CLUSTER"
| fieldsAdd activeGateId = dt.metadata[activegate_id], activeGateVersion = dt.metadata[activegate_version]
| filter in(activeGateId, $ActiveGateId)
| filter matchesValue(name, $Cluster)
| filter isNotNull(activeGateId)
// Fetch the ActiveGate's JVM self-monitoing metrics for
// - CPU usage [%]
// - Memory available and used [bytes]
// - Garbage collection time [ms]
| lookup [
  timeseries {
    cpu_usage = max(dt.sfm.active_gate.jvm.cpu_usage),
    memory_available = max(dt.sfm.active_gate.jvm.heap_memory_available),
    memory_used = max(dt.sfm.active_gate.jvm.heap_memory_used),
    gc_time = max(dt.sfm.active_gate.jvm.gc.major_collection_time)
  },
  by:{dt.active_gate.id},
  shift:-3m
  // Memory used percent is not available as a separate metric and therefore calculated
  | fieldsAdd memory_used_percent = memory_used[] / memory_available[] * 100
  // Determine if an ActiveGate is unhealthy:
  // - CPU usage exceeds 85% for more than 3 samples within the last 30 minutes
  // - Memory usage exceeds 80% for more than 3 samples within the last 30 minutes
  // - Garbage collection time exceeds 3 seconds for more than 3 samples within the last 30 minutes
  | fieldsAdd
    unhealthy_cpu_usage = arraySum(iCollectArray(if(cpu_usage[] > 85, 1, else: 0))) > 3,
    high_memory_usage = arraySum(iCollectArray(if(memory_used_percent[] > 80, 1, else: 0))) > 3,
    high_gc_time = arraySum(iCollectArray(if(gc_time[] > 3000, 1, else: 0))) > 3
  // Memory usage is unhealthy if the uage or garbage collection times are high
  | fieldsAdd unhealthy_memory_usage = high_memory_usage or high_gc_time
], sourceField:{activeGateId}, lookupField:{dt.active_gate.id}, fields:{unhealthy_cpu_usage, unhealthy_memory_usage}, executionOrder:leftFirst
// Map the unhealthy states to human readable text
| fieldsAdd conditions = arrayRemoveNulls(array(
  if(unhealthy_cpu_usage, "High CPU usage", else:null),
  if(unhealthy_memory_usage, "High memory usage", else:null)
))
// Show only unhealthy
| filter arraySize(conditions) > 0
// Create an intent link to the cluster connection settings
| fieldsAdd Actions = concat("[Connection settings](/ui/intent/dynatrace.settings/open_settings#%7B%22settings.entityId%22%3A%22", toString(id), "%22%2C%22settings.itemId%22%3A%22kubernetes-cluster-connection%22%7D)")
| fieldsAdd `ActiveGate ID` = concat("[", activeGateId, "](/ui/intent/dynatrace.fleet.management/view-entity-dt.smartscape.activegate#%7B%22dt.active_gate.id%22%3A%22", activeGateId, "%22%7D)")
| fields id, Cluster = name, `ActiveGate ID`, `ActiveGate version` = activeGateVersion, Conditions = conditions, Actions

18.query:
// Fetch the ActiveGate's JVM self-monitoring metric for CPU usage
timeseries {
    cpu_usage = max(dt.sfm.active_gate.jvm.cpu_usage)
  },
  by:{dt.active_gate.id},
  shift:-3m,
  // Filter by selected ActiveGate
  filter: in(dt.active_gate.id, $ActiveGateId)
// Filter by selected cluster name
// The in-lookup expression is used as the cluster name is not available as a dimension
| filter in(dt.active_gate.id, lookup(
    [ smartscapeNodes "K8S_CLUSTER" | filter matchesValue(name, $Cluster) | fields activeGateId = dt.metadata[activegate_id] ],
    sourceField:dt.active_gate.id, lookupField:activeGateId, executionOrder:leftFirst
  )[activeGateId])

19.query:
// Fetch the ActiveGate's JVM self-monitoring metric for available memory and memory usage
timeseries {
    memory_available = max(dt.sfm.active_gate.jvm.heap_memory_available),
    memory_used = max(dt.sfm.active_gate.jvm.heap_memory_used)
  },
  by:{dt.active_gate.id},
  shift:-3m,
  // Filter by selected ActiveGate
  filter: in(dt.active_gate.id, $ActiveGateId)
// Calculate the memory usage in percent
| fieldsAdd memory_used_percent = memory_used[] / memory_available[] * 100
| fieldsRemove memory_used, memory_available
// Filter by selected cluster name
// The in-lookup expression is used as the cluster name is not available as a dimension
| filter in(dt.active_gate.id, lookup(
    [ smartscapeNodes "K8S_CLUSTER" | filter matchesValue(name, $Cluster) | fields activeGateId = dt.metadata[activegate_id] ],
    sourceField:dt.active_gate.id, lookupField:activeGateId, executionOrder:leftFirst
  )[activeGateId])

20.query:
// Fetch the ActiveGate's JVM self-monitoring metric for garbage collection time
timeseries {
    gc_time = max(dt.sfm.active_gate.jvm.gc.major_collection_time)
  },
  by:{dt.active_gate.id},
  shift:-3m,
  // Filter by selected ActiveGate
  filter: in(dt.active_gate.id, $ActiveGateId)
// Filter by selected cluster name
// The in-lookup expression is used as the cluster name is not available as a dimension
| filter in(dt.active_gate.id, lookup(
    [ smartscapeNodes "K8S_CLUSTER" | filter matchesValue(name, $Cluster) | fields activeGateId = dt.metadata[activegate_id] ],
    sourceField:dt.active_gate.id, lookupField:activeGateId, executionOrder:leftFirst
  )[activeGateId])
